import appCss from "../styles.css?url";
import { reportLovableError } from "../lib/lovable-error-reporting";
import { PlatformProvider, usePlatform } from '@/components/PlatformContext';
import { PlatformHeader } from '@/components/PlatformHeader';
import { ChatWidget } from '@/components/ChatWidget';
import { MapExperience, MapShortcut } from '@/components/MapExperience';

function NotFoundComponent() {
  return (
    <div className="flex min-h-screen items-center justify-center bg-background px-4">
      <div className="max-w-md text-center">
        <h1 className="text-7xl font-bold text-foreground">404</h1>
        <h2 className="mt-4 text-xl font-semibold text-foreground">Page not found</h2>
        <p className="mt-2 text-sm text-muted-foreground">
          The page you're looking for doesn't exist or has been moved.
        </p>
        <div className="mt-6">
          <Link
            to="/"
            className="inline-flex items-center justify-center rounded-md bg-primary px-4 py-2 text-sm font-medium text-primary-foreground transition-colors hover:bg-primary/90"
          >
            Go home
          </Link>
        </div>
      </div>
    </div>
  );
}

function ErrorComponent({ error, reset }: ErrorComponentProps) {
  console.error(error);
  const router = useRouter();
  useEffect(() => {
    reportLovableError(error, { boundary: "tanstack_root_error_component" });
  }, [error]);

  return (
    <div className="flex min-h-screen items-center justify-center bg-background px-4">
      <div className="max-w-md text-center">
        <h1 className="text-xl font-semibold tracking-tight text-foreground">
          This page didn't load
        </h1>
        <p className="mt-2 text-sm text-muted-foreground">
          Something went wrong on our end. You can try refreshing or head back home.
        </p>
        <div className="mt-6 flex flex-wrap justify-center gap-2">
          <button
            onClick={() => {
              router.invalidate();
              reset();
            }}
            className="inline-flex items-center justify-center rounded-md bg-primary px-4 py-2 text-sm font-medium text-primary-foreground transition-colors hover:bg-primary/90"
          >
            Try again
          </button>
          <a
            href="/"
            className="inline-flex items-center justify-center rounded-md border border-input bg-background px-4 py-2 text-sm font-medium text-foreground transition-colors hover:bg-accent"
          >
            Go home
          </a>
        </div>
      </div>
    </div>
  );
}

export const Route = createRootRouteWithContext<{ queryClient: QueryClient }>()({
  head: () => ({
    // Replace these placeholders with the app's name and description when first building the app.
    // Each content route, / included, must still set its own head(). Never add og:image or
    // twitter:image here: every page without its own would inherit the root's preview image.
    meta: [
      { charSet: "utf-8" },
      { name: "viewport", content: "width=device-width, initial-scale=1" },
      { title: "AgroSat SP" },
      { name: "description", content: "Climate and satellite data for São Paulo farmers" },
      { name: "author", content: "Lovable" },
      { property: "og:title", content: "AgroSat SP" },
      { property: "og:description", content: "Climate and satellite data for São Paulo farmers" },
      { property: "og:type", content: "website" },
      { property: "og:locale", content: "en_US" },
      { name: "twitter:card", content: "summary_large_image" },
      { name: "twitter:site", content: "@Lovable" },
    ],
    links: [
      {
        rel: "stylesheet",
        href: appCss,
      },
      { rel: "stylesheet", href: "https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;600&family=Space+Grotesk:wght@400;500;600;700&display=swap" },
      { rel: "icon", href: "/favicon.ico", type: "image/x-icon" },
    ],
  }),
  shellComponent: RootShell,
  component: RootComponent,
  notFoundComponent: NotFoundComponent,
  errorComponent: ErrorComponent,
});

function RootShell({ children }: { children: ReactNode }) {
  return (
    <html lang="en">
      <head>
        <HeadContent />
      </head>
      <body>
        {children}
        <Scripts />
      </body>
    </html>
  );
}

function RootComponent() {
  const { queryClient } = Route.useRouteContext();

  return (
    <QueryClientProvider client={queryClient}>
      {/* Required: nested routes render here. Removing <Outlet /> breaks all child routes. */}
      <PlatformProvider>
        <PlatformShell />
      </PlatformProvider>
    </QueryClientProvider>
  );
}

function PlatformShell() {
  const { mapOpen, hasSelectedLocation } = usePlatform();
  const expanded = mapOpen || !hasSelectedLocation;
  const [mapPresent, setMapPresent] = useState(true);
  const showMap = expanded || mapPresent;
  const leavingMap = !expanded && mapPresent;

  useEffect(() => {
    if (expanded) {
      setMapPresent(true);
      return;
    }
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
      setMapPresent(false);
      return;
    }

    // Release the map even if the browser interrupts the animation.
    const timeout = window.setTimeout(() => setMapPresent(false), 450);
    return () => window.clearTimeout(timeout);
  }, [expanded]);

  return (
    <div className={showMap ? "flex h-dvh flex-col overflow-hidden" : "flex min-h-dvh flex-col"}>
      <PlatformHeader />
      <div className="relative flex min-h-0 flex-1 flex-col">
        <div className={expanded ? "hidden" : undefined} data-location-reveal={leavingMap}>
          <Outlet />
        </div>
        {showMap && (
          <div
            className="absolute inset-0 z-10 flex flex-col"
            data-map-leaving={leavingMap}
            aria-hidden={leavingMap}
            inert={leavingMap}
            onAnimationEnd={(event) => {
              if (leavingMap && event.target === event.currentTarget) setMapPresent(false);
            }}
          >
            <MapExperience />
          </div>
        )}
      </div>
      <ChatWidget />
      <MapShortcut />
    </div>
  );
}
